mapper.select:
SELECT overview.gameCode, overview.betGold, overview.rewardGold, overview.participants FROM ( SELECT 'luck' AS gameCode, IFNULL(SUM(r.total_input), 0) AS betGold, IFNULL(SUM(r.total_output), 0) AS rewardGold, COUNT(DISTINCT r.uid) AS participants FROM play_luck_record r JOIN `user` u ON u.uid = r.uid AND u.region_id = r.region_id WHERE r.create_time BETWEEN #{startTime} AND #{endTime}
UNION ALL SELECT 'wheel', IFNULL(SUM(r.gold_num), 0), IFNULL(SUM(r.reward_num), 0), COUNT(DISTINCT r.uid) FROM play_wheel_record r JOIN `user` u ON u.uid = r.uid WHERE r.create_time BETWEEN #{startTime} AND #{endTime}
UNION ALL SELECT 'zool', IFNULL(SUM(r.gold_num), 0), IFNULL(SUM(r.reward_num), 0), COUNT(DISTINCT r.uid) FROM play_zool_record r JOIN `user` u ON u.uid = r.uid WHERE r.create_time BETWEEN #{startTime} AND #{endTime}
UNION ALL SELECT 'tarot', IFNULL(SUM(r.gold_num), 0), IFNULL(SUM(r.reward_num), 0), COUNT(DISTINCT r.uid) FROM play_tarot_record r JOIN `user` u ON u.uid = r.uid WHERE r.create_time BETWEEN #{startTime} AND #{endTime}
UNION ALL SELECT 'third', IFNULL(SUM(CASE WHEN r.type = 1 THEN r.gold_num ELSE 0 END), 0), IFNULL(SUM(CASE WHEN r.type = 2 THEN r.gold_num ELSE 0 END), 0), COUNT(DISTINCT r.uid) FROM game_record r JOIN `user` u ON u.uid = r.uid AND u.region_id = r.region_id WHERE r.create_time BETWEEN #{startTime} AND #{endTime}
) overview ORDER BY FIELD(overview.gameCode, 'luck', 'wheel', 'zool', 'tarot', 'third')

SELECT segment.segmentCode, SUM(segment.plays) AS plays, SUM(segment.inputGold) AS inputGold, SUM(segment.outputGold) AS outputGold FROM ( SELECT CASE r.open_type WHEN 0 THEN 'probability' WHEN 1 THEN 'publicPool' WHEN 2 THEN 'personalPool' END AS segmentCode, IFNULL(SUM(r.times), 0) AS plays, IFNULL(SUM(r.total_input), 0) AS inputGold, IFNULL(SUM(r.total_output), 0) AS outputGold FROM play_luck_record r JOIN `user` u ON u.uid = r.uid AND u.region_id = r.region_id WHERE r.open_type IN (0, 1, 2) AND r.create_time BETWEEN #{startTime} AND #{endTime}
GROUP BY r.open_type UNION ALL SELECT CASE f.type WHEN 1 THEN 'fixedManual' WHEN 2 THEN 'fixedAuto' END, COUNT(0), IFNULL(SUM(f.input), 0), IFNULL(SUM(f.output), 0) FROM play_luck_fixed_input f JOIN `user` u ON u.uid = f.uid AND u.region_id = f.region_id WHERE f.type IN (1, 2) AND f.input IS NOT NULL AND f.output IS NOT NULL AND f.create_time BETWEEN #{startTime} AND #{endTime}
GROUP BY f.type ) segment WHERE segment.segmentCode IS NOT NULL GROUP BY segment.segmentCode ORDER BY FIELD(segment.segmentCode, 'probability', 'publicPool', 'personalPool', 'fixedManual', 'fixedAuto')
